#include <cstdio>
#include <algorithm>
using namespace std;

#define ll long long
const ll INF = 1LL << 60;

ll N, K, h[100010], dp[100010];

inline void chmin(ll& a, ll b) {
    if (a > b) {
        a = b;
    }
}

int main() {
    scanf("%lld %lld", &N, &K);
    for (int i = 0; i < N; i++) {
        scanf("%lld", &h[i]);
    }
    fill(dp + 1, dp + N, INF); // Only fill from index 1 to N-1 with INF
    dp[0] = 0;

    for (int i = 0; i < N; i++) {
        for (int j = i + 1; j <= min(i + K, N - 1); j++) {
 chmin(dp[j], dp[i] + abs(h[i] - h[j]));
        }
    }

    printf("%lld\n", dp[N - 1]);
}

