ll N, K, h[100010], dp[100010];

void chmin(ll& a, ll b) {
    if (a > b) {
        a = b;
    }
}

int main() {
    scanf("%lld %lld", &N, &K);
    for (int i = 0; i < N; i++) {
        scanf("%lld", &h[i]);
    }
    fill(dp, dp + N, INF);
    dp[0] = 0;

    for (int i = 0; i < N; i++) {
        for (int j = i + 1; j <= min(i + K, N - 1); j++) {
 chmin(dp[j], dp[i] + abs(h[i] - h[j]));
        }
    }

    printf("%lld\n", dp[N - 1]);
}

